<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

        <div class="@cssClass">
            @if (isCompleted && !isCurrent)
            {
                <button type="button" class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                    <span class="step-icon">&#10003;</span>
                    <span class="step-label">@StepNames[step]</span>
                </button>
            }
            else
            {
                <span class="step-icon">@(step + 1)</span>
                <span class="step-label">@StepNames[step]</span>
            }
        </div>

        @if (i < StepNames.Count - 1)
        {
            <div class="step-connector @(isCompleted ? "completed" : "")"></div>
        }
    }
</nav>

