+    background: #2563eb;
+    color: white;
+    font-weight: 600;
+}
+
+.step.completed {
+    color: #16a34a;
+}
+
+.step.future {
+    color: #9ca3af;
+}
+
+.step-button {
+    background: none;
+    border: none;
+    color: inherit;
+    cursor: pointer;
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    font-size: inherit;
+    padding: 0;
+}
+
+.step-button:hover {
+    text-decoration: underline;
+}
+
+.step-icon {
+    display: inline-flex;
+    align-items: center;
+    justify-content: center;
+    width: 1.75rem;
+    height: 1.75rem;
+    border-radius: 50%;
+    border: 2px solid currentColor;
+    font-size: 0.75rem;
+    font-weight: 700;
+}
+
+.step.current .step-icon {
+    border-color: white;
+}
+
+.step-connector {
